/// <summary>
/// DebuC 03.12.24
/// </summary>
[DataContract]
[SysOperationAlwaysInitializeAttribute]
[SysOperationContractProcessing(classStr(NDXExcelPriceJournalImportUIBuilder))]
public class NDXExcelPriceJournalImportContract implements SysOperationInitializable, SysOperationValidatable
{
    private NDXExcelFileId                  excelFileId;
    private PriceDiscJournalNum             priceDiscJournalNum;
    private NDXSignature                    signature;
    private PriceType                       relation;
    private PriceDiscAccountRelation        accountRelation;
    private PriceDiscProductCode            itemCode;
    private PriceDiscPartyCode              accountCode;
    private FromDate                        fromDate;

}

Method.Source:
/// <summary>
/// DebuC 03.12.24
/// </summary>
/// <param name = "_excelFileId">NDXExcelFileId</param>
/// <returns>NDXExcelFileId</returns>
[DataMemberAttribute("Excel-Definition")]
public NDXExcelFileId parmExcelFileId(NDXExcelFileId _excelFileId = excelFileId)
{
    excelFileId = _excelFileId;
    return excelFileId;
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
/// <param name = "_priceDiscJournalNum">PriceDiscJournalNum</param>
/// <returns>PriceDiscJournalNum</returns>
[DataMemberAttribute("Journal")]
public PriceDiscJournalNum parmPriceDiscJournalNum(PriceDiscJournalNum _priceDiscJournalNum = priceDiscJournalNum)
{
    priceDiscJournalNum = _priceDiscJournalNum;
    return priceDiscJournalNum;
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
/// <param name = "_signature">NDXSignature</param>
/// <returns>NDXSignature</returns>
[DataMemberAttribute("Signatur")]
public NDXSignature parmSignature(NDXSignature _signature = signature)
{
    Signature = _signature;
    return Signature;
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
/// <param name = "_relation">PriceType</param>
/// <returns>PriceType</returns>
[DataMemberAttribute("Relation")]
public PriceType parmRelation(PriceType _relation = relation)
{
    relation = _relation;
    return relation;
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
/// <param name = "_accountRelation">PriceDiscAccountRelation</param>
/// <returns>PriceDiscAccountRelation</returns>
[DataMemberAttribute("Kontoauswahl")]
public PriceDiscAccountRelation parmAccountRelation(PriceDiscAccountRelation _accountRelation = accountRelation)
{
    accountRelation = _accountRelation;
    return accountRelation;
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
/// <param name = "_itemCode">PriceDiscProductCode</param>
/// <returns>PriceDiscProductCode</returns>
[DataMemberAttribute("ArtikelCode")]
public PriceDiscProductCode parmItemCode(PriceDiscProductCode _itemCode = ItemCode)
{
    itemCode = _itemCode;
    return itemCode;
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
/// <param name = "_accountCode">PriceDiscPartyCode</param>
/// <returns>PriceDiscPartyCode</returns>
[DataMemberAttribute("KontoCode")]
public PriceDiscPartyCode parmAccountCode(PriceDiscPartyCode _accountCode = accountCode)
{
    accountCode = _accountCode;
    return accountCode;
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
public void initialize()
{
    signature = NDXHelperCommon::Signature();
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
/// <param name = "_fromDate">FromDate</param>
/// <returns>FromDate</returns>
public FromDate parmFromDate(FromDate _fromDate = fromDate)
{
    fromDate = _fromDate;
    return fromDate;
}

/// <summary>
/// DebuC 03.12.24
/// </summary>
/// <returns>boolean</returns>
public boolean validate()
{
    boolean isValid = true;

    if(!excelFileId || !NDXExcelTable::find(excelFileId))
    {
        isValid = checkFailed(strFmt("Zur Excel-Definition %1 konnte kein Datensatz gefunden werden!", excelFileId));
    }
    if(!priceDiscJournalNum || !PriceDiscAdmTable::find(priceDiscJournalNum))
    {
        isValid = checkFailed(strFmt("Zur Journal-Nr. %1 konnte kein Datensatz gefunden werden!", priceDiscJournalNum));
    }
    if(!signature)
    {
        isValid = checkFailed("Signatur darf nicht leer sein");
    }

    return isValid;
}
